import json
runs = {2:(3,10),4:(4,24),5:(3,6),6:(17,26),7:(4,14),9:(2,6),10:(8,16),
        11:(3,11),12:(5,17),14:(6,14),15:(10,20),17:(0,13),18:(2,4),
        19:(1,4),20:(6,18),21:(11,24),22:(2,4)}
out=[[1]*28 for _ in range(23)]
for i,(a,b) in runs.items():
    for c in range(a,b+1):
        out[i][c] = 0 if (c-a)%2==0 else 1
    # fill gaps between consecutive zeros
    for c in range(a+1,b):
        if (c-a)%2==1:
            out[i][c]=2
# sanity: verify against demo rule = cells between consecutive 0s
for i,r in enumerate(out):
    zs=[c for c,v in enumerate(r) if v==0]
    assert all(r[z]==0 for z in zs)
print(len(out), set(len(r) for r in out))
s=json.dumps(out)
print(s)
print("twos:", sum(r.count(2) for r in out))
